const fs = require("fs");
const path = require("path");

const BASE = "/PATH/TO/RESUME_SYSTEM_ROOT/builds";

const VOCAB_PATH = path.join(BASE,"vocab_learning");
const DICT_PATH = path.join(BASE,"dictionaries");

const TOKEN_FILE = path.join(VOCAB_PATH,"jd_token_candidates.json");
const BIGRAM_FILE = path.join(VOCAB_PATH,"jd_bigram_candidates.json");

const MIN_COUNT = 50;

// ------------------------------
// Helpers
// ------------------------------

function readJSON(file){
  try{
    const raw = fs.readFileSync(file,"utf8");
    return raw.trim() ? JSON.parse(raw) : {};
  }catch(e){
    return {};
  }
}

function filterAndSort(dict){
  return Object.entries(dict)
    .filter(([k,v]) => (v.count || 0) >= MIN_COUNT)
    .sort((a,b) => (b[1].count || 0) - (a[1].count || 0))
    .map(([token,data]) => ({
      token,
      count: data.count,
      examples: data.examples
    }));
}

// ------------------------------
// Load dictionaries
// ------------------------------

const PHRASE_MAP = readJSON(path.join(DICT_PATH,"phrase_map.json"));
const TOKEN_MAP = readJSON(path.join(DICT_PATH,"token_map.json"));
const DOMAIN_SIGNALS = readJSON(path.join(DICT_PATH,"domain_signals.json"));

// ------------------------------
// Load candidates
// ------------------------------

const tokenCandidates = readJSON(TOKEN_FILE);
const bigramCandidates = readJSON(BIGRAM_FILE);

const tokens = filterAndSort(tokenCandidates);
const bigrams = filterAndSort(bigramCandidates);

// ------------------------------
// Load canonical from INPUT
// ------------------------------

const canonical = $input.first().json.canonical_profile_object || {};
const bulletBank = canonical.bullet_bank || [];

// ------------------------------
// Reference sets
// ------------------------------

const phraseOutputs = new Set(Object.values(PHRASE_MAP));
const tokenKeys = new Set(Object.keys(TOKEN_MAP));
const tokenValues = new Set(Object.values(TOKEN_MAP));
const domainTokens = new Set(Object.values(DOMAIN_SIGNALS).flat());

// ------------------------------
// Canonical token universe
// ------------------------------

const canonicalTokens = new Set([
  ...phraseOutputs,
  ...tokenValues,
  ...domainTokens
]);

// ------------------------------
// JD token set
// ------------------------------

const jdTokenSet = new Set(tokens.map(t => t.token));

// ------------------------------
// Tokenizer
// ------------------------------

function extractTokens(text){

  let normalized = (text || "").toLowerCase();

  const phrases = Object.keys(PHRASE_MAP)
    .sort((a,b)=>b.length-a.length);

  for(const phrase of phrases){
    normalized = normalized.replaceAll(phrase, PHRASE_MAP[phrase]);
  }

  const tokens = normalized
    .replace(/[^\w\s]/g," ")
    .split(/\s+/)
    .filter(w => w.length > 2);

  return tokens.map(t => TOKEN_MAP[t] || t);
}

// ------------------------------
// Build bullet token set
// ------------------------------

const bulletTokenSet = new Set();

for(const b of bulletBank){
  const tokens = extractTokens(b.text);
  tokens.forEach(t => bulletTokenSet.add(t));
}

// ------------------------------
// Dictionary Health
// ------------------------------

// Dead tokens
const dead_tokens = [];

for(const token of canonicalTokens){
  if(!jdTokenSet.has(token) && !bulletTokenSet.has(token)){
    dead_tokens.push(token);
  }
}

// Orphan canonical
const orphan_canonical_tokens = [];

for(const token of canonicalTokens){
  if(!domainTokens.has(token)){
    orphan_canonical_tokens.push(token);
  }
}

// Domain coverage + gap
const domain_coverage = {};

for(const [domain, signals] of Object.entries(DOMAIN_SIGNALS)){

  let jd_hits = 0;
  let bullet_hits = 0;

  for(const s of signals){
    if(jdTokenSet.has(s)) jd_hits++;
    if(bulletTokenSet.has(s)) bullet_hits++;
  }

  domain_coverage[domain] = {
    signal_count: signals.length,
    jd_hits,
    bullet_hits,
    gap: jd_hits - bullet_hits
  };
}

// ------------------------------
// Validation
// ------------------------------

const unmapped_tokens = [];
const orphan_tokens = [];
const no_evidence_tokens = [];
const unknown_bullet_tokens = [];
const prioritized_fixes = [];

function isMapped(token){
  return (
    phraseOutputs.has(token) ||
    tokenKeys.has(token) ||
    tokenValues.has(token)
  );
}

function isInDomain(token){
  return domainTokens.has(token);
}

// JD validation
for(const t of tokens){

  const token = t.token;

  const mapped = isMapped(token);
  const inDomain = isInDomain(token);
  const inBullets = bulletTokenSet.has(token);

  if(!mapped) unmapped_tokens.push({ token, count: t.count });
  if(!inDomain) orphan_tokens.push({ token, count: t.count });
  if(!inBullets) no_evidence_tokens.push({ token, count: t.count });

  let priority = t.count;
  if(!mapped) priority *= 2;
  if(!inDomain) priority *= 1.5;
  if(!inBullets) priority *= 1.5;

  if(!mapped || !inDomain || !inBullets){
    prioritized_fixes.push({
      token,
      count: t.count,
      mapped,
      inDomain,
      inBullets,
      priority_score: Math.round(priority)
    });
  }
}

// Bullet validation
for(const token of bulletTokenSet){

  const inDict =
    phraseOutputs.has(token) ||
    tokenKeys.has(token) ||
    tokenValues.has(token);

  if(!inDict){
    unknown_bullet_tokens.push(token);
  }
}

// ------------------------------
// Token Trace (NEW)
// ------------------------------

const tokenUniverse = new Set([
  ...jdTokenSet,
  ...bulletTokenSet,
  ...canonicalTokens
]);

const token_trace = {};

for(const token of tokenUniverse){

  const mapped = isMapped(token);
  const inDomain = isInDomain(token);
  const inJD = jdTokenSet.has(token);
  const inBullets = bulletTokenSet.has(token);

  let status = "healthy";

  if(!mapped) status = "unmapped";
  else if(!inDomain) status = "no_domain";
  else if(!inBullets) status = "no_evidence";
  else if(!inJD) status = "unused";

  token_trace[token] = {
    jd: inJD,
    mapped,
    domain: inDomain,
    bullet: inBullets,
    status
  };
}

// ------------------------------
// Sort fixes
// ------------------------------

prioritized_fixes.sort((a,b) => b.priority_score - a.priority_score);

// ------------------------------
// Copy-friendly outputs
// ------------------------------

const TOP_N = 40;

const prioritized_token_list = prioritized_fixes
  .slice(0, TOP_N)
  .map(x => x.token);

// ------------------------------
// Output
// ------------------------------

return [{
  json:{
    threshold: MIN_COUNT,
dictionary_health: {
      dead_tokens,
      orphan_canonical_tokens,
      domain_coverage
    },
    token_candidates: tokens,
    bigram_candidates: bigrams,
    bigram_fixes: bigrams.map(x => x.token),



    validation: {
      prioritized_fixes,
      prioritized_token_list,
      unmapped_tokens,
      unmapped_tokens_strings: unmapped_tokens.map(x => x.token),
      orphan_tokens,
      orphan_tokens_strings: orphan_tokens.map(x => x.token),
      no_evidence_tokens,
      no_evidence_tokens_strings: no_evidence_tokens.map(x => x.token),
      unknown_bullet_tokens
    },

    token_trace
  }
}];

const fs = require("fs");
const path = require("path");

const BASE = "/PATH/TO/RESUME_SYSTEM_ROOT/builds";

const VOCAB_PATH = path.join(BASE,"vocab_learning");
const DICT_PATH = path.join(BASE,"dictionaries");

const TOKEN_CAND_FILE = path.join(VOCAB_PATH,"jd_token_candidates.json");
const BIGRAM_CAND_FILE = path.join(VOCAB_PATH,"jd_bigram_candidates.json");

const TOKEN_MAP_FILE = path.join(DICT_PATH,"token_map.json");
const PHRASE_MAP_FILE = path.join(DICT_PATH,"phrase_map.json");
const DOMAIN_SIGNALS_FILE = path.join(DICT_PATH,"domain_signals.json");
const STOPWORDS_FILE = path.join(DICT_PATH,"stopwords.json");

/* ---------- helpers ---------- */

function readJSON(file){
  try{
    const raw = fs.readFileSync(file,"utf8");
    return raw.trim() ? JSON.parse(raw) : {};
  }catch(e){
    return {};
  }
}

function writeJSON(file,obj){
  fs.writeFileSync(file,JSON.stringify(obj,null,2));
}

/* ---------- load candidate pools ---------- */

let tokenCandidates = readJSON(TOKEN_CAND_FILE);
let bigramCandidates = readJSON(BIGRAM_CAND_FILE);

/* ---------- load dictionaries ---------- */

const tokenMap = readJSON(TOKEN_MAP_FILE);
const phraseMap = readJSON(PHRASE_MAP_FILE);
const domainSignals = readJSON(DOMAIN_SIGNALS_FILE);
const stopwords = readJSON(STOPWORDS_FILE);

/* ---------- build known vocabulary set ---------- */

const knownVocab = new Set([
  ...Object.keys(tokenMap),
  ...Object.values(tokenMap),
  ...Object.values(phraseMap),
  ...Object.values(domainSignals).flat(),
  ...stopwords
]);

/* ---------- clean token candidates ---------- */

let removedTokens = 0;

for(const token of Object.keys(tokenCandidates)){

  if(knownVocab.has(token)){
    delete tokenCandidates[token];
    removedTokens++;
  }

}

/* ---------- clean bigram candidates ---------- */

let removedBigrams = 0;

for(const phrase of Object.keys(bigramCandidates)){

  if(knownVocab.has(phrase)){
    delete bigramCandidates[phrase];
    removedBigrams++;
  }

}

/* ---------- save cleaned files ---------- */

writeJSON(TOKEN_CAND_FILE,tokenCandidates);
writeJSON(BIGRAM_CAND_FILE,bigramCandidates);

/* ---------- return summary ---------- */

return [{
  json:{
    removed_tokens: removedTokens,
    removed_bigrams: removedBigrams
  }
}];
